<?php
namespace App\Http\Controllers\Api;
use App\Http\Controllers\Controller; use App\Http\Requests\QuotationRequestStoreRequest; use App\Http\Requests\QuotationRequestUpdateRequest; use App\Http\Requests\UpdateQuotationStatusRequest; use App\Http\Resources\QuotationRequestResource; use App\Models\QuotationRequest; use Illuminate\Http\JsonResponse; use Illuminate\Http\Request; use Illuminate\Http\Resources\Json\AnonymousResourceCollection; use Illuminate\Support\Facades\DB;
class QuotationRequestController extends Controller {
 private function visible(): \Illuminate\Database\Eloquent\Builder { $q=QuotationRequest::with(['user','items.product.category']); return request()->user()->isAdmin() ? $q : $q->where('user_id',request()->user()->id); }
 public function index(Request $r): AnonymousResourceCollection { $q=$this->visible()->when($r->status,fn($x,$status)=>$x->where('status',$status))->when($r->search,fn($x,$s)=>$x->where(fn($z)=>$z->where('project_title','like',"%$s%")->orWhere('project_location','like',"%$s%")->orWhereHas('user',fn($u)=>$u->where('name','like',"%$s%"))))->latest(); return QuotationRequestResource::collection($q->paginate($r->integer('per_page',10))->withQueryString()); }
 public function store(QuotationRequestStoreRequest $r): JsonResponse { $quote=DB::transaction(function() use($r){$quote=$r->user()->quotationRequests()->create($r->safe()->except('items')); $quote->items()->createMany($r->validated('items')); return $quote;}); return response()->json(['message'=>'Quotation request submitted.','data'=>new QuotationRequestResource($quote->refresh()->load(['user','items.product.category']))],201); }
 public function show(QuotationRequest $quotationRequest): QuotationRequestResource { $this->authorizeAccess($quotationRequest); return new QuotationRequestResource($quotationRequest->load(['user','items.product.category'])); }
 public function update(QuotationRequestUpdateRequest $r,QuotationRequest $quotationRequest): QuotationRequestResource { DB::transaction(function() use($r,$quotationRequest){$quotationRequest->update($r->safe()->except('items'));$quotationRequest->items()->delete();$quotationRequest->items()->createMany($r->validated('items'));}); return new QuotationRequestResource($quotationRequest->fresh()->load(['user','items.product.category'])); }
 public function destroy(QuotationRequest $quotationRequest): JsonResponse { $this->authorizeAccess($quotationRequest); abort_unless($quotationRequest->status==='pending'||request()->user()->isAdmin(),422,'Only pending requests can be deleted.'); $quotationRequest->delete(); return response()->json(null,204); }
 public function updateStatus(UpdateQuotationStatusRequest $r,QuotationRequest $quotationRequest): QuotationRequestResource { $allowed=['pending'=>['quoted','rejected'],'accepted'=>['completed']]; abort_unless(in_array($r->status,$allowed[$quotationRequest->status]??[],true),422,'Invalid status transition.'); $quotationRequest->update($r->validated()); return new QuotationRequestResource($quotationRequest->load(['user','items.product.category'])); }
 public function accept(QuotationRequest $quotationRequest): QuotationRequestResource { $this->authorizeAccess($quotationRequest); abort_unless(!request()->user()->isAdmin() && $quotationRequest->status==='quoted',422,'Only quoted requests can be accepted.'); $quotationRequest->update(['status'=>'accepted']); return new QuotationRequestResource($quotationRequest->load(['user','items.product.category'])); }
 private function authorizeAccess(QuotationRequest $q): void { abort_unless(request()->user()->isAdmin()||$q->user_id===request()->user()->id,403); }
}
